/* Story data: original game dialogue; no copied song lyrics. */
window.KROVO_STORY = {"meta":{"title":"КРОВОСТОК — Четверг / Пятница","subtitle":"Многоперсонажная чат-новелла. Оригинальная игровая адаптация сюжетов песен.","provenance":["«Голова» — чистая квартира, голова неизвестного мужчины в пакете «Дикси» на кухонном столе; сохраняем отсутствие доказанного объяснения.","«Коромысло» — Андрей убит, безымянный убийца; Валерик извлекает из памяти сведения о тайниках, делёж пополам.","«Шурик» — звонок с Филиппин, старые долги и желание оставить прошлое позади; не обязательно связан с другими происшествиями.","«Летом» — бытовой летний день похитителя и заложник Шомпол в подполе, срок денег до седьмого. Здесь только отдельная предварительная линия через Томазика.","«Патологоанатом» — профессиональное соседство с телесным сюрреализмом; не даём чудесного универсального опознания.","«Подозрение» — сомнения человека, который слишком хочет увидеть общую скрытую схему; его версии могут быть ложными."],"original_inventions":["Серёга как имя героя «Головы»; Марат как имя подозревающего; игрок без фиксированной биографии; новый чат между ними.","Телефонные связи игрока с персонажами, конкретные сообщения, варианты реплик, действия полиции/Томазика/Аллы и последствия пересылок.","Общие события не образуют автоматически один заговор. Межпесенные знакомства и причинные связи — только наша игровая надстройка."],"state":{"head_first":["photo","police","details"],"photo_route":["doctor","valerik","private"],"shurik_mode":["truth","ask","friendly"],"val_mode":["quiet","question","relay"],"killer_mode":["literal","refuse","confront"],"cross_mode":["separate","mention","money"],"rumor_mode":["contained","speculation","leave"],"theory_mode":["challenge","spread","ignore"],"cellar_mode":["careful","identify","leave"],"shurik_end":["warm","past","silent"],"sergey_end":["leave","tomorrow","observe"],"last_choice":["stop","head","split"]},"design":"12 решений, 3 ответа в каждом. Варианты поздних сообщений условно проверяют предыдущие выборы. Игрок не может отмотать чужую жизнь, но меняет распределение сведений, доверие и последствия распространения слухов. Нет таймеров ожидания, свободного ввода и обязательного универсального злодея.","version":"0.2.0","scenes":23,"author":"Игровая адаптация byGagarin","copyright":"Оригинальные игровые диалоги. Полные тексты песен не включены."},"scenes":[{"id":"E01","title":"09:04 — Не к завтраку","chat":"Серёга","core":[{"who":"Серёга","text":"Ты проснулся?","kind":"in"},{"who":"Серёга","text":"У меня дома посторонний.","kind":"in"},{"who":"Серёга","text":"Точнее, часть постороннего. На кухонном столе, в пакете из «Дикси». Мужик какой-то. Лет тридцать.","kind":"in"},{"who":"Серёга","text":"Крови нет. Бардака нет. Дверь закрыта была. Я чайник поставил, а потом уже вспомнил, что надо кому-нибудь написать.","kind":"in"},{"who":"Серёга","text":"Ты же живой? Ответь.","kind":"in"}],"choices":[{"id":"A","title":"Попросить фотографию","echo":"Фотографию покажи.","set":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Сейчас.","kind":"in"},{"who":"Серёга","text":"[фото: раскрытый пакет, лицо неизвестного мужчины; рядом кружка и хлебница]","kind":"media"},{"who":"Серёга","text":"Лицо отдельно не снимал. У меня к нему претензий нет, зачем мне крупным планом.","kind":"in"}],"note":"Получаем фото пакета, но не опознание."},{"id":"B","title":"Предложить вызвать полицию","echo":"Звони в полицию. Это не тот случай, где надо гадать.","set":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Позвоню. Сначала кофе долью. Не буду же им потом объяснять, почему у меня кружка недопитая.","kind":"in"},{"who":"Серёга","text":"Только ты никуда это не пересылай. Я тебя просто в известность поставил.","kind":"in"}],"note":"Серёга сообщает властям и особенно просит не разносить историю."},{"id":"C","title":"Спросить про обстоятельства","echo":"Ты проверил замок, окна и что было вчера?","set":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Замок закрыт. Окна закрыты. Вчера я дома был, макароны варил. Макароны съел.","kind":"in"},{"who":"Серёга","text":"Сегодня у меня на столе голова. Видимо, меню разнообразится.","kind":"in"}],"note":"Узнаём детали, снимка пока нет."}]},{"id":"E02","title":"09:19 — Кому показывать","chat":"Серёга","core":[{"who":"Серёга","text":"Я сейчас ещё раз посмотрел. Всё на своих местах. Даже холодильник шумит как обычно.","kind":"in"},{"who":"Серёга","text":"Есть вообще человек, который может сказать, что делать с такой хернёй?","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Из дежурной части сказали не трогать. Великолепный совет. Я и так не собирался с ним обниматься.","kind":"in"}],"note":""},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Вот то фото, что прислал, кому показывать собрались?","kind":"in"}],"note":""},{"when":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Если надо — сфотографирую. Только мне не хочется всю жизнь хранить такой снимок в галерее.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Показать патологоанатому","echo":"Есть один врач. Спрошу, может ли он что-нибудь сказать.","set":{"photo_route":"doctor"},"lines":[{"who":"Серёга","text":"Если он попросит остальные части, то у меня остальные части отсутствуют.","kind":"in"},{"who":"Система","text":"Контакт «Док» появился в списке недавних.","kind":"sys"},{"who":"Док","text":"[переслано из чата «Серёга»: фото и вопрос о неизвестном мужчине]","kind":"out"}],"note":"Док получает данные только о находке; лицо неизвестно."},{"id":"B","title":"Переслать Валерику","echo":"Спрошу Валерика. Он странными задачами занимается.","set":{"photo_route":"valerik"},"lines":[{"who":"Серёга","text":"Только с подписью «не моё». Мне ещё кредит за телевизор закрывать, не хватало уголовного дела.","kind":"in"},{"who":"Система","text":"В чат «Валерик» отправлена фотография пакета и сообщение о находке.","kind":"sys"},{"who":"Валерик","text":"[переслано из чата «Серёга»: фотография и сообщение о находке]","kind":"out"}],"note":"Валерик знает, что у Серёги есть голова. Это позже узнаёт убийца."},{"id":"C","title":"Не распространять снимок","echo":"Пока никому. Разберись сам с тем, кто должен приехать.","set":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Вот. Адекватное мнение. Я тебя за это и ценю.","kind":"in"},{"who":"Серёга","text":"Если завтра в пакете появятся ноги, я напишу. Сейчас меня не отвлекай, я есть собираюсь.","kind":"in"}],"note":"Сведений о голове больше никто не получает автоматически."}]},{"id":"E03","title":"10:06 — С другого берега","chat":"Шурик","core":[{"who":"Шурик","text":"Димон, живой? Это Шура.","kind":"in"},{"who":"Шурик","text":"Тут у меня море. Настоящее. Без льда, без машин на берегу и без дураков с автоматами.","kind":"in"},{"who":"Шурик","text":"Я, короче, остаюсь. Сначала думал — месяца на три, а теперь понял, что мне и триста лет тут нормально.","kind":"in"},{"who":"Шурик","text":"Ты Кольку давно видел? Я его старый номер потерял.","kind":"in"}],"choices":[{"id":"A","title":"Сразу сказать, что ошибся","echo":"Это не Димон. Номер, видимо, перепутал.","set":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"А. Ну, отлично. Значит, я постороннему человеку уже про море рассказал.","kind":"in"},{"who":"Шурик","text":"Кольку если увидишь — скажи, что мы с ним квиты. Он мне не должен. И я ему тоже. Так и передай, без деталей.","kind":"in"},{"who":"Шурик","text":"А ты будь здоров, кто бы ты ни был.","kind":"in"}],"note":"Шурик не узнаёт о других контактах. Его история остаётся отдельной."},{"id":"B","title":"Уточнить, что с Колькой","echo":"Кольку не видел. А чего ты его ищешь?","set":{"shurik_mode":"ask"},"lines":[{"who":"Шурик","text":"Не ищу. Просто решил, что на старости лет хорошо бы закрыть старые разговоры.","kind":"in"},{"who":"Шурик","text":"Было время, мы таких вопросов друг другу задавали, что потом приходилось окна в машине менять.","kind":"in"},{"who":"Шурик","text":"Если ему попадёшься, передай: ничего не должен. Только пусть больше не звонит со старых номеров.","kind":"in"}],"note":"Появляется бытовой контекст девяностых; никаких биткоинов или тайных списков."},{"id":"C","title":"Поддержать разговор","echo":"Море — дело хорошее. Ты там надолго?","set":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Судя по всему, навсегда. Тут одна женщина мне сказала, что по утрам надо сначала завтракать, а уже потом решать проблемы.","kind":"in"},{"who":"Шурик","text":"Я эту идею до сорока лет проверял бы — не додумался.","kind":"in"},{"who":"Шурик","text":"Всё, я побежал. Кольку увижу — сам ему скажу про долги. Если вспомню зачем.","kind":"in"}],"note":"Шурик исчезает на время, довольный жизнью, без обязаловки решать сюжет о голове."}]},{"id":"E04","title":"11:38 — Специалисты","chat":"Валерик","core":[{"who":"Валерик","text":"Слушай, если тебе напишут насчёт меня, скажи: я до вечера занят.","kind":"in"},{"who":"Валерик","text":"Не «не беру трубку». Именно занят. Это разные вещи.","kind":"in"},{"who":"Валерик","text":"И не давай никому мой домашний номер.","kind":"in"}],"variants":[{"when":{"photo_route":"doctor"},"lines":[{"who":"Док","text":"Ты мне чью-то голову в личку прислал в одиннадцать утра. Я, конечно, много видел, но хочу напомнить: по фотографии я человека не вскрываю.","kind":"in"},{"who":"Док","text":"Если он не шевелится, это ещё не вся информация, которую мне нужно сообщить. С официальными вопросами — в соответствующие службы.","kind":"in"},{"who":"Док","text":"И да. Скажи хозяину: пакет не превращает предмет в продукт. Я сегодня как раз с такими спорами закончил.","kind":"in"}],"note":"Док отказывает в чудесном опознании."},{"when":{"photo_route":"valerik"},"lines":[{"who":"Валерик","text":"А насчёт снимка: человека не узнаю. Видел сегодня другого покойника. Тоже, знаешь ли, неразговорчивый.","kind":"in"},{"who":"Валерик","text":"И фото больше никому не рассылай. Глупо, когда одну чужую смерть начинают приписывать другой.","kind":"in"}],"note":"Валерик чётко разделяет покойников, но сам факт находки уже известен."},{"when":{"photo_route":"private"},"lines":[{"who":"Валерик","text":"День хороший. Никто ещё не прислал мне ничего лишнего. Даже странно.","kind":"in"}],"note":"Валерик не знает о голове."}],"choices":[{"id":"A","title":"Согласиться и не лезть","echo":"Ладно, если кто спросит — ты занят.","set":{"val_mode":"quiet"},"lines":[{"who":"Валерик","text":"Вот за это спасибо. Нормально сформулированная информация — нынче редкость.","kind":"in"}],"note":"Игрок не вмешивается в дело Коромысла."},{"id":"B","title":"Спросить, что случилось","echo":"Валер, что за срочность?","set":{"val_mode":"question"},"lines":[{"who":"Валерик","text":"Один человек решил, что мёртвый Андрей всё равно должен ему деньги.","kind":"in"},{"who":"Валерик","text":"Технически мысль не самая глупая. Способ реализации — совершенно ебанутый.","kind":"in"},{"who":"Валерик","text":"Я тебе потом напишу, если это будет смешно. Сейчас пока только противно.","kind":"in"}],"note":"Игрок знает об Андрее раньше, но не о личности убийцы."},{"id":"C","title":"Предложить передать сообщение","echo":"Могу передать одному твоему человеку, что ты на месте.","set":{"val_mode":"relay"},"lines":[{"who":"Валерик","text":"Не надо. Я сам знаю, кому и что должен говорить.","kind":"in"},{"who":"Валерик","text":"Ты хороший человек, но твоя привычка пересылать всё подряд однажды кого-нибудь достанет. Не обязательно тебя.","kind":"in"}],"note":"Валерик начинает осторожнее давать информацию игроку."}]},{"id":"E05","title":"12:41 — Андрей не отвечает","chat":"Без имени","core":[{"who":"Без имени","text":"Валерик сказал, ты у него есть в контактах.","kind":"in"},{"who":"Без имени","text":"Телефон заряжен? Не пропадай.","kind":"in"},{"who":"Без имени","text":"Я Андрюху Коромысло убил. В порыве. Ничего героического, просто разозлился.","kind":"in"},{"who":"Без имени","text":"А потом выяснилось, что все места, где у него лежат деньги, он держал в собственной голове.","kind":"in"},{"who":"Без имени","text":"Валерик может это вытащить. Он умный. А я вечно сначала делаю, потом думаю.","kind":"in"},{"who":"Без имени","text":"Если он спросит, говори: я ничего не прячу. Мне нужны мои деньги, а не лекции.","kind":"in"}],"variants":[{"when":{"photo_route":"valerik"},"lines":[{"who":"Без имени","text":"И что там у вас за фотография чужой башки гуляет? Валерик спрашивал, не нашего ли клиента нашли.","kind":"in"},{"who":"Без имени","text":"Это не Андрей. Я Андрея видел с очень близкого расстояния. Уж поверь.","kind":"in"}],"note":"Из-за пересылки фото убийца узнаёт о Сергее, но голова не объявляется Коромыслом."}],"choices":[{"id":"A","title":"Передать сообщение буквально","echo":"Передам Валерику дословно.","set":{"killer_mode":"literal"},"lines":[{"who":"Без имени","text":"Дословно — хорошо. Ты там ничего от себя не добавляй, я и сам умею испортить впечатление.","kind":"in"}],"note":"Валерик увидит требование без редактирования."},{"id":"B","title":"Отказаться быть посредником","echo":"Я тебя не знаю. И в твоё дело не полезу.","set":{"killer_mode":"refuse"},"lines":[{"who":"Без имени","text":"Правильное решение. Я бы на твоём месте тоже отказался.","kind":"in"},{"who":"Без имени","text":"Валерик всё равно в курсе. Просто сказал тебе, потому что говорить вслух сегодня особенно мерзко.","kind":"in"}],"note":"Дело продолжается без помощи игрока."},{"id":"C","title":"Напомнить, что речь об убийстве","echo":"Ты понимаешь, что написал признание в убийстве незнакомому человеку?","set":{"killer_mode":"confront"},"lines":[{"who":"Без имени","text":"Понимаю.","kind":"in"},{"who":"Без имени","text":"Незнакомые обычно хоть слушают. Знакомые почему-то сразу спрашивают про деньги.","kind":"in"},{"who":"Без имени","text":"Ладно. Зря написал. Удали, если тебе так спокойнее.","kind":"in"}],"note":"Игрок получает прямое признание; доверия больше не становится."}]},{"id":"E06","title":"13:05 — Что знает Валерик","chat":"Валерик","core":[{"who":"Валерик","text":"Мне сейчас один прекрасный человек объяснил, что хочет получить наследство раньше покойника.","kind":"in"},{"who":"Валерик","text":"Не спрашивай, как устроена техника. Тебе не понравится.","kind":"in"},{"who":"Валерик","text":"Мне нужен только список мест. Человеку — деньги. С этим всё ясно.","kind":"in"},{"who":"Валерик","text":"А дальше — как получится.","kind":"in"}],"variants":[{"when":{"killer_mode":"literal"},"lines":[{"who":"Валерик","text":"Ты его слова прислал как есть. Молодец. Теперь хотя бы я знаю, что он не собирается торговаться. Пока.","kind":"in"}],"note":""},{"when":{"killer_mode":"refuse"},"lines":[{"who":"Валерик","text":"Он сказал, ты отказался передавать. Нормально. Я бы тоже отказался. Что с меня возьмёшь, я уже в деле.","kind":"in"}],"note":""},{"when":{"killer_mode":"confront"},"lines":[{"who":"Валерик","text":"Ты спросил его про убийство. Он теперь всем доказывает, что это была ошибка в коммуникации. Дурацкое слово, да.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Оставить историю отдельной","echo":"Разбирайтесь сами. Только чужую голову сюда не приплетайте.","set":{"cross_mode":"separate"},"lines":[{"who":"Валерик","text":"Именно. Люблю, когда события не мешают в одну кашу.","kind":"in"},{"who":"Валерик","text":"У меня сейчас вполне достаточно одного трупа.","kind":"in"}],"note":"Сведения о Сергее не расширяются; история Коромысла живёт самостоятельно."},{"id":"B","title":"Упомянуть Серёгину находку","echo":"Кстати, у знакомого дома на столе неизвестная голова. Ты ничего об этом не слышал?","set":{"cross_mode":"mention"},"lines":[{"who":"Валерик","text":"Слышал только от тебя. Или от твоего друга — если ты уже рассылал снимок.","kind":"in"},{"who":"Валерик","text":"Нет, не надо делать вид, что две смерти автоматически связаны. Это ты не следователь, а человек с телефоном.","kind":"in"},{"who":"Валерик","text":"Но адрес человека мне не отправляй. Ему сейчас точно не нужны мои знакомые.","kind":"in"}],"note":"Валерик знает подробность: голова в квартире. Это создаст побочный риск слуха."},{"id":"C","title":"Спросить о деньгах","echo":"Если список получишь, вы оба будете богаты?","set":{"cross_mode":"money"},"lines":[{"who":"Валерик","text":"Деньги — слово широкое. Они там в виде чисел, которые очень радуют людей, не умеющих считать.","kind":"in"},{"who":"Валерик","text":"Я, в отличие от некоторых, умею. А вот делиться не люблю.","kind":"in"},{"who":"Валерик","text":"Договор уже есть. Половина мне, половина человеку с нервами.","kind":"in"}],"note":"Игрок получает сведения о долях. Это нельзя переносить на Шурика без его собственного участия."}]},{"id":"E07","title":"14:22 — Беспокойство Серёги","chat":"Серёга","core":[{"who":"Серёга","text":"Ты там вообще как?","kind":"in"},{"who":"Серёга","text":"Я вот уборку закончил. Не из-за головы, просто по четвергам у меня уборка.","kind":"in"},{"who":"Серёга","text":"Пакет пока на месте. По нему решения нет.","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Полиция перезвонила. Приедут, как освободятся. Прелесть. Хорошо, что я не пирог в духовку поставил.","kind":"in"}],"note":""},{"when":{"photo_route":"doctor"},"lines":[{"who":"Серёга","text":"Доктор твой чего? Не узнал? Ну ладно. Меня это не удивляет, у мужика лицо какое-то совершенно незнакомое.","kind":"in"}],"note":""},{"when":{"photo_route":"valerik"},"lines":[{"who":"Серёга","text":"Твой Валера написал мне с незнакомого номера. Спросил, где именно пакет лежит.","kind":"in"},{"who":"Серёга","text":"Я ему ответил: «Там, где и утром». Он почему-то обиделся.","kind":"in"}],"note":""},{"when":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Знаешь, приятно, что никто из чужих пока не спрашивает, что у меня на завтрак.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Серёга","text":"Кстати, кто-то спрашивал, в квартире ли это. Ты всем мой адрес рассказываешь?","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Остановить распространение","echo":"Больше никому ничего не пересылай. Я тоже не буду.","set":{"rumor_mode":"contained"},"lines":[{"who":"Серёга","text":"Идёт. Мне вообще не нравится, когда моя кухня превращается в общественное место.","kind":"in"},{"who":"Серёга","text":"Пойду макароны сварю. Вчера нормально получились.","kind":"in"}],"note":"Слух ограничен текущими контактами."},{"id":"B","title":"Спросить разрешение показать ещё одному","echo":"Есть человек, который любит искать совпадения. Можно ему без адреса показать снимок?","set":{"rumor_mode":"speculation"},"lines":[{"who":"Серёга","text":"А мне за это что будет?","kind":"in"},{"who":"Серёга","text":"Хотя ладно, показывай. Только пусть сначала объяснит, зачем ему моя голова. В смысле та.","kind":"in"}],"note":"Открывает Марата, автора ложных теорий. Голову начинают обсуждать публичнее."},{"id":"C","title":"Не обсуждать больше голову","echo":"Понял. Скажешь потом, чем кончилось.","set":{"rumor_mode":"leave"},"lines":[{"who":"Серёга","text":"Вот и договорились. Я тоже пока не хочу с ней разговаривать.","kind":"in"},{"who":"Серёга","text":"С ней — это с проблемой, если что. Саму голову я не спрашивал. Не настолько ещё всё плохо.","kind":"in"}],"note":"Серёга действует самостоятельно; игрок теряет часть сведений."}]},{"id":"E08","title":"16:02 — Человек со схемой","chat":"Марат (версии)","core":[{"who":"Марат","text":"Ты же вчера говорил, что люди в случайности верят. Я думал, ты шутишь.","kind":"in"},{"who":"Марат","text":"Я тут вывел одну закономерность. В городе стало слишком много людей, которым надо срочно что-то забыть.","kind":"in"},{"who":"Марат","text":"Старые деньги, новые деньги, старые друзья — у всех всё сходится. Только у меня почему-то не сходится.","kind":"in"}],"variants":[{"when":{"rumor_mode":"speculation"},"lines":[{"who":"Марат","text":"Фотографию получил. Вот смотри: вчера кто-то говорит про тайник, сегодня у кого-то голова. Я бы подумал.","kind":"in"},{"who":"Марат","text":"Правда, людей с головами у нас много. Это немного мешает теории.","kind":"in"}],"note":""},{"when":{"rumor_mode":"contained"},"lines":[{"who":"Марат","text":"Ты даже фотографию не прислал. Отлично. Теперь мне не на что опереться, кроме собственного подозрения.","kind":"in"}],"note":""},{"when":{"rumor_mode":"leave"},"lines":[{"who":"Марат","text":"Ты ничего не рассказываешь. Поэтому на всякий случай скажу: молчание тоже умеет совпадать.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Попросить доказательства","echo":"Назови один факт, а не пять красивых совпадений.","set":{"theory_mode":"challenge"},"lines":[{"who":"Марат","text":"Справедливое замечание.","kind":"in"},{"who":"Марат","text":"Я двадцать лет ловил одну закономерность. И вдруг понял, что она может существовать только в моей голове.","kind":"in"},{"who":"Марат","text":"Пока не знаю, хорошо это или плохо. Наверное, сначала поем.","kind":"in"}],"note":"Марат сам сомневается и перестаёт раздувать связь."},{"id":"B","title":"Разрешить ему распространять версию","echo":"Ладно, спроси у своих, кто слышал про эти случаи.","set":{"theory_mode":"spread"},"lines":[{"who":"Марат","text":"Вот! Уже работаем.","kind":"in"},{"who":"Марат","text":"Сейчас накидаю в чат района. Названий не будет. Только наводящие вопросы.","kind":"in"}],"note":"Сплетня выйдет за пределы знакомых; Серёга потеряет контроль над информацией."},{"id":"C","title":"Не ввязываться","echo":"Ты без меня пока. Я сегодня и так насмотрелся на совпадения.","set":{"theory_mode":"ignore"},"lines":[{"who":"Марат","text":"Ладно. Только если окажется, что всё это разные события, ты мне не забудь сказать.","kind":"in"},{"who":"Марат","text":"Я, честно говоря, очень хочу, чтоб оказались.","kind":"in"}],"note":"Не получает новые версии, но и не распространяет сплетню."}]},{"id":"E09","title":"18:36 — Магазин закрывается","chat":"Томазик","core":[{"who":"Томазик","text":"Ты не занят? У меня мужик с соседней улицы весь день по два раза ходил. Покупал хлеб, молоко, потом опять хлеб.","kind":"in"},{"who":"Томазик","text":"Я спросил, зачем столько. Он говорит: «Кормить надо». Сказал нормально, без шуток.","kind":"in"},{"who":"Томазик","text":"А ещё Алла утром спрашивала, не слышно ли чего у них из подвала.","kind":"in"},{"who":"Томазик","text":"Я магазин держу, мне за сплетни не платят. А ты людей знаешь. Чего там?","kind":"in"}],"choices":[{"id":"A","title":"Попросить Аллу проверить без риска","echo":"Алле скажи, чтобы сама туда не ходила. Если слышит кого-то — пусть зовёт помощь.","set":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Передам. И правильно, у меня через час закрытие, я чужие подвалы посещать не собираюсь.","kind":"in"},{"who":"Томазик","text":"Но странный он. Смеялся над акцией на пельмени. Никто над ней не смеётся, там реально скидка.","kind":"in"}],"note":"Алла предупреждена, что не надо входить в дом; линия Шомпола остаётся отдельной, но помощь возможна."},{"id":"B","title":"Спросить имя мужчины","echo":"Кто ходил? Имя есть?","set":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Имени не помню. Он всегда на наличные берёт. А Алла его как-то называла, но я тогда холодильник размораживал.","kind":"in"},{"who":"Томазик","text":"У меня всё равно двадцать минут до закрытия. Если вспомню — напишу.","kind":"in"}],"note":"Игрок получает лишь неполное свидетельство; человек не становится общим злодеем."},{"id":"C","title":"Не вмешиваться в разговоры у магазина","echo":"Не знаю. Если всё тихо, не лезь в чужой дом.","set":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Согласен. Я лучше ценники поменяю.","kind":"in"},{"who":"Томазик","text":"Только Алла что-то сегодня беспокойная. Ну, её дело.","kind":"in"}],"note":"Томазик никого не предупреждает. События линии «Летом» идут сами."}]},{"id":"E10","title":"21:16 — Последний звонок","chat":"Шурик","core":[{"who":"Шурик","text":"Слушай. Я тут почему-то номер не удалил.","kind":"in"},{"who":"Шурик","text":"У меня на пляже парень из Омска. Двадцать лет с женой ругается, но домой всё равно звонит. Говорит: привычка.","kind":"in"},{"who":"Шурик","text":"Вот и я думаю, что зря раньше по привычке людям жизнь портил.","kind":"in"},{"who":"Шурик","text":"Кольку если встретишь, скажи: он мне больше ничего не должен. Впрочем, и мне он тоже.","kind":"in"},{"who":"Шурик","text":"И тебе, незнакомец, спокойной ночи. Я у себя тут уже позавтракал.","kind":"in"}],"variants":[{"when":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"Забавно, что я всё это вообще не тому человеку рассказываю. Но с Колькой я бы так спокойно не смог.","kind":"in"}],"note":""},{"when":{"shurik_mode":"ask"},"lines":[{"who":"Шурик","text":"Старые долги нельзя считать каждый день. А то вместо солнца опять будут одни цифры.","kind":"in"}],"note":""},{"when":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Ты, кстати, хороший собеседник. Не задаёшь лишних вопросов о том, как я туда попал.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Ответить тепло","echo":"И тебе хорошего дня. Береги себя.","set":{"shurik_end":"warm"},"lines":[{"who":"Шурик","text":"Постараюсь. Сегодня, во всяком случае, никого убивать не собираюсь. Для праздника достаточно.","kind":"in"}],"note":"Шурик завершает свою историю добрым бытовым сообщением."},{"id":"B","title":"Спросить о старых делах","echo":"А чего ты всё-таки из России уехал?","set":{"shurik_end":"past"},"lines":[{"who":"Шурик","text":"Долго рассказывать. Неинтересно особенно. Молодой был, дурак был, думал — навсегда таким останусь.","kind":"in"},{"who":"Шурик","text":"А теперь вот бананы ем и боюсь только, что интернет отключится посреди разговора.","kind":"in"}],"note":"Можно раскрыть кусочек биографии, но он не связан с головой и биткоинами."},{"id":"C","title":"Не отвечать","echo":"[Не отвечать]","set":{"shurik_end":"silent"},"lines":[{"who":"Система","text":"Шурик был в сети в 21:19. Больше сообщений нет.","kind":"sys"}],"note":"Отсутствие ответа — допустимый выбор; миру не требуется мгновенная реакция игрока."}]},{"id":"E11","title":"23:48 — Нормальный вечер","chat":"Серёга","core":[{"who":"Серёга","text":"Я тут решил, что пора спать. День странный, но за электричество заплатил. Хоть что-то полезное.","kind":"in"},{"who":"Серёга","text":"Мне вот интересно, ты почему всегда думаешь, что на всё должен найтись ответ?","kind":"in"},{"who":"Серёга","text":"Я с утра несколько раз посмотрел на эту херню и всё ещё не понимаю ничего. Может, и не пойму.","kind":"in"}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Кстати, приехали люди, всё оформили и забрали пакет. В квартире даже просторнее не стало.","kind":"in"}],"note":""},{"when":{"rumor_mode":"contained"},"lines":[{"who":"Серёга","text":"Спасибо, что не превратил мой стол в городской чат. Серьёзно. У меня и без того соседи лишнего знают.","kind":"in"}],"note":""},{"when":{"rumor_mode":"speculation"},"lines":[{"who":"Серёга","text":"Какой-то знакомый твоего знакомого уже спрашивает про магазин «Дикси». Я ему написал: «У нас ещё «Пятёрочка» есть, хотите список?»","kind":"in"}],"note":""},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"Вот теперь в районном чате спрашивают, у кого пропала голова. Восемьдесят человек гадают и ни один не предлагает её поискать.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Серёга","text":"И запомни: чужим людям не нужно знать, в какой квартире я живу. Даже если люди умные.","kind":"in"}],"note":""}],"choices":[{"id":"A","title":"Принять, что ответа может не быть","echo":"Да. Не всё надо раскручивать сегодня. Спокойной ночи.","set":{"sergey_end":"leave"},"lines":[{"who":"Серёга","text":"Вот. Нормально поговорили.","kind":"in"},{"who":"Серёга","text":"Если завтра проснусь и на столе будет вторая, я тебе не напишу. Шутка. Наверное.","kind":"in"}],"note":"Не решает загадку, но сохраняет отношения."},{"id":"B","title":"Предложить разобраться завтра","echo":"Давай завтра. По свежей голове лучше соображать.","set":{"sergey_end":"tomorrow"},"lines":[{"who":"Серёга","text":"По свежей — это ты сейчас неудачно выразился.","kind":"in"},{"who":"Серёга","text":"Ладно. Завтра так завтра. Я холодильник только закрою.","kind":"in"}],"note":"Игрок сохраняет возможность продолжить локальную линию."},{"id":"C","title":"Попросить написать, если что-то изменится","echo":"Просто сообщи, если что-то изменится. Без теорий.","set":{"sergey_end":"observe"},"lines":[{"who":"Серёга","text":"Хорошо. Если изменится, напишу.","kind":"in"},{"who":"Серёга","text":"Сам тоже не мешай мне отдыхать. Я с сегодняшнего дня считаю это серьёзной работой.","kind":"in"}],"note":"Пассивное наблюдение вместо расследования."}]},{"id":"E12","title":"05:14 — Разделили","chat":"Валерик","core":[{"who":"Валерик","text":"Уже утро, если ты ещё не спал.","kind":"in"},{"who":"Валерик","text":"Список достали. Техническая часть сработала.","kind":"in"},{"who":"Валерик","text":"Человек, который вчера признался тебе в убийстве, больше не спрашивает про пароли. Он спрашивает, почему у меня такая довольная физиономия.","kind":"in"},{"who":"Валерик","text":"Договорились пополам. Ему хватит. Мне тоже.","kind":"in"},{"who":"Валерик","text":"Андрея, разумеется, это не вернуло. И никогда не было такой задачи.","kind":"in"}],"variants":[{"when":{"cross_mode":"separate"},"lines":[{"who":"Валерик","text":"Про твою другую историю я ничего не знаю. И не хочу знать. По отдельности жизнь хотя бы помещается в календарь.","kind":"in"}],"note":""},{"when":{"cross_mode":"mention"},"lines":[{"who":"Валерик","text":"И ещё: Серёге не писал. Фотографию никому не отправлял. Мне одного мёртвого сегодня достаточно.","kind":"in"}],"note":""},{"when":{"cross_mode":"money"},"lines":[{"who":"Валерик","text":"Вот тебе обещанная арифметика: половина и половина. Никто не стал делать вид, что убитый нам что-то добровольно подарил.","kind":"in"}],"note":""},{"when":{"theory_mode":"spread"},"lines":[{"who":"Валерик","text":"Слышал, в районе уже увязали мою работу с каким-то пакетом. У людей талант устраивать расследование, не выходя из сортира.","kind":"in"}],"note":""},{"when":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Алле передал. Она сказала, что без посторонних никуда не пойдёт. И что у неё к тому дому давно вопросы.","kind":"in"},{"who":"Система","text":"Неизвестно, помогло ли это Шомполу. Его история ещё не закончилась.","kind":"sys"}],"note":""},{"when":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Алла больше не заходила. Мужик всё-таки купил ещё хлеб. Я закрыл магазин.","kind":"in"},{"who":"Система","text":"Шомпол остаётся в подполе в пределах известных событий. Его дальнейший исход здесь не показан.","kind":"sys"}],"note":""},{"when":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Вспомнил только прозвище. Короткое и дурацкое. Скажу, когда снова зайдёт.","kind":"in"},{"who":"Система","text":"Имя похитителя не установлено. История Шомпола не привязана к Андрею Коромысло.","kind":"sys"}],"note":""}],"choices":[{"id":"A","title":"Закончить разговор","echo":"Всё. Пожалуй, хватит на сегодня.","set":{"last_choice":"stop"},"lines":[{"who":"Валерик","text":"Поддерживаю. Я тоже впервые за сутки хочу просто поспать.","kind":"in"}],"note":"Игрок сознательно не ищет общую разгадку."},{"id":"B","title":"Спросить о голове","echo":"А неизвестного в пакете ты так и не знаешь?","set":{"last_choice":"head"},"lines":[{"who":"Валерик","text":"Нет.","kind":"in"},{"who":"Валерик","text":"Иногда неизвестный человек остаётся неизвестным. Это, если честно, гораздо обычнее, чем людям хочется.","kind":"in"}],"note":"Подчёркивает самостоятельность историй."},{"id":"C","title":"Спросить, почему делили именно так","echo":"Почему пополам? Он же сам всё испортил.","set":{"last_choice":"split"},"lines":[{"who":"Валерик","text":"Потому что я не умею убивать, а он не умеет читать память. Люди иногда идеально дополняют друг друга. Отвратительное, конечно, обстоятельство.","kind":"in"}],"note":"Закрывает историю «Коромысло» без оправдания убийства."}]},{"id":"F01","title":"Пятница, 09:18 — Нормальное продолжение","chat":"Серёга","core":[{"who":"Серёга","text":"Пятница наступила. Никакой символики, просто пятница.","kind":"in"},{"who":"Серёга","text":"Чайник сломался. Вчера работал, сегодня кипятит воду с таким видом, будто я ему денег должен.","kind":"in"},{"who":"Серёга","text":"Ты вчера что-нибудь узнал по моей истории? Без версий про международный синдикат, пожалуйста.","kind":"in"}],"choices":[{"id":"A","title":"Ответить, что ясности нет","echo":"Нет. Человека никто надёжно не опознал.","set":{"frank_head":"unknown"},"lines":[{"who":"Серёга","text":"Ну и ладно. Хуже всего, когда начинают уверенно врать.","kind":"in"}],"note":""},{"id":"B","title":"Обсудить публикацию снимка","echo":"Снимок кто-нибудь ещё видел, кроме тех, кому мы отправляли?","set":{"frank_head":"spread"},"lines":[{"who":"Серёга","text":"Не знаю. Я сегодня впервые пожалел, что когда-то научился пользоваться интернетом.","kind":"in"}],"note":""},{"id":"C","title":"Спросить про быт","echo":"А ты сам как? Спал хоть?","set":{"frank_head":"care"},"lines":[{"who":"Серёга","text":"Спал. Очень даже хорошо. Во сне голова не снилась. Мне, кстати, картошка снилась. Нормальная, крупная.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Если ты про пакет: его вчера забрали. Бумажку выдали. У меня теперь вместо головы номер дела.","kind":"in"}]},{"when":{"head_first":"photo"},"lines":[{"who":"Серёга","text":"Снимок я удалил из галереи. Пока удалял, телефон спросил: «Создать воспоминание?» Потрясающая техника.","kind":"in"}]},{"when":{"head_first":"details"},"lines":[{"who":"Серёга","text":"Пакет я не разворачивал второй раз. Моё любопытство умерло где-то после завтрака.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"А ещё мне сосед написал, что я якобы торгую головами. Спасибо людям за рекламу.","kind":"in"}]}]},{"id":"F02","title":"Пятница, 10:03 — У магазина","chat":"Томазик","core":[{"who":"Томазик","text":"Утро, дружище. Ты вчера про мужика спрашивал. Я вспомнил, где видел его машину.","kind":"in"},{"who":"Томазик","text":"У дома с глухими окнами, за остановкой. Он с утра два раза заходил ко мне за хлебом.","kind":"in"},{"who":"Томазик","text":"Алла опять интересовалась, что там у них внизу. Я ей сказал, что магазин справок о подвалах не выдаёт.","kind":"in"}],"choices":[{"id":"A","title":"Передать осторожное предупреждение","echo":"Попроси Аллу не заходить туда одной. Если кто-то просит помощи — пусть зовёт службы.","set":{"alla_signal":"caution"},"lines":[{"who":"Томазик","text":"Передам. И отдельно скажу, что я не консультирую по чужим подвалам даже за деньги.","kind":"in"}],"note":""},{"id":"B","title":"Попросить контакт Аллы","echo":"Можешь дать ей мой номер? Хочу уточнить, что она сама слышала.","set":{"alla_signal":"contact"},"lines":[{"who":"Томазик","text":"Дам. Скажу, что ты не полиция. Не обещаю, что она обрадуется.","kind":"in"}],"note":""},{"id":"C","title":"Не развивать разговор","echo":"Ясно. Лучше не лезть, пока ничего толком не известно.","set":{"alla_signal":"quiet"},"lines":[{"who":"Томазик","text":"Может, и так. Я, во всяком случае, чужую дверь открывать не собираюсь.","kind":"in"}],"note":""}],"variants":[{"when":{"cellar_mode":"careful"},"lines":[{"who":"Томазик","text":"Кстати, Алла вчера спасибо сказала за предупреждение. Не знаю, за что именно, но спасибо.","kind":"in"}]},{"when":{"cellar_mode":"identify"},"lines":[{"who":"Томазик","text":"Я про прозвище вспомнил только одно: его все почему-то называют коротким словом. По имени никто не обращается.","kind":"in"}]},{"when":{"cellar_mode":"leave"},"lines":[{"who":"Томазик","text":"Я вчера никому не звонил. Но Алла утром сама пришла: говорит, шум опять был.","kind":"in"}]}]},{"id":"F03","title":"Пятница, 10:47 — Алла","chat":"Алла","core":[{"who":"Алла","text":"Томазик дал мне твой номер. Я сама попросила. Говорит, ты про дом спрашивал.","kind":"in"},{"who":"Алла","text":"Я вчера там была. Уходила уже поздно. Во дворе вроде никого, а из-под пола кто-то три раза стукнул.","kind":"in"},{"who":"Алла","text":"Не знаю, что это было. Может, трубы. Я не мастер по трубам.","kind":"in"},{"who":"Алла","text":"Ты чего хочешь узнать?","kind":"in"}],"choices":[{"id":"A","title":"Спросить лишь о звуке","echo":"Ты точно слышала три стука? Из дома или с улицы?","set":{"alla_detail":"sound"},"lines":[{"who":"Алла","text":"Из дома. Три раза и потом пауза. Время почти одиннадцать было. Записала, чтобы не забыть.","kind":"in"}],"note":""},{"id":"B","title":"Назвать подозрение прямо","echo":"Есть опасение, что внизу держат человека. Я не уверен.","set":{"alla_detail":"warning"},"lines":[{"who":"Алла","text":"Это уже не про трубы. И хорошо, что сказал «не уверен». От уверенных людей у меня самые большие проблемы.","kind":"in"}],"note":""},{"id":"C","title":"Не втягивать её в риск","echo":"Пока ничего не делай. Просто будь осторожна.","set":{"alla_detail":"gentle"},"lines":[{"who":"Алла","text":"Я и не собиралась туда возвращаться. Мне завтра на работу, а не в кино ужасов.","kind":"in"}],"note":""}],"variants":[{"when":{"alla_signal":"caution"},"lines":[{"who":"Алла","text":"И спасибо, что через Томазика сказал не ходить одной. Удивительно, что кому-то это нужно отдельно объяснять.","kind":"in"}]},{"when":{"alla_signal":"contact"},"lines":[{"who":"Алла","text":"Томазик предупредил, что ты будешь спрашивать. Ладно, расскажу как было.","kind":"in"}]},{"when":{"alla_signal":"quiet"},"lines":[{"who":"Алла","text":"Не знаю зачем пишу. Томазик сказал, что ты вчера хотя бы слушал, не строил версии.","kind":"in"}]}]},{"id":"F04","title":"Пятница, 11:26 — Вторая работа","chat":"Док","core":[{"who":"Док","text":"Между прочим, в нашей профессии крайне удобно, когда люди не требуют узнать судьбу по одному пикселю.","kind":"in"},{"who":"Док","text":"Мне сегодня снова пишут незнакомые люди и спрашивают, что можно узнать по фотографии. Иногда даже самой фотографии не прикладывают.","kind":"in"}],"choices":[{"id":"A","title":"Попросить не распространять","echo":"Можешь просто больше никому это не пересылать?","set":{"doc_reply":"closed"},"lines":[{"who":"Док","text":"Могу. Уже не пересылал. У меня, к счастью, есть куда более скучная работа.","kind":"in"}],"note":""},{"id":"B","title":"Уточнить источник","echo":"Писали разные люди или один и тот же?","set":{"doc_reply":"source"},"lines":[{"who":"Док","text":"Разные номера. Но две подписи совпадают слово в слово. Это говорит о копировании, а не о заговоре.","kind":"in"}],"note":""},{"id":"C","title":"Сменить тему","echo":"Забудь про фото. Скажи лучше, что у тебя с работой.","set":{"doc_reply":"distance"},"lines":[{"who":"Док","text":"Всё нормально. Я работаю, люди умирают, соседи спорят, кто забрал мою доставку. Жизнь идёт.","kind":"in"}],"note":""}],"variants":[{"when":{"photo_route":"private"},"lines":[{"who":"Док","text":"Ты лично мне, кстати, ничего не присылал. Даже приятно. Но слух дошёл и без тебя.","kind":"in"}]},{"when":{"photo_route":"doctor"},"lines":[{"who":"Док","text":"А твой снимок я никому не передавал. Он сам уже давно живёт своей отдельной жизнью.","kind":"in"}]},{"when":{"photo_route":"valerik"},"lines":[{"who":"Док","text":"Ты мне вчера не писал, но кто-то фотографию переслал. Раз уж начали — я не определю личность по такому качеству.","kind":"in"}]}]},{"id":"F05","title":"Пятница, 12:18 — Доля","chat":"Без имени","core":[{"who":"Без имени","text":"Ну что, доброе утро. У Валерика половина. У меня половина.","kind":"in"},{"who":"Без имени","text":"У Андрея, понятно, ничего. Мертвецам с дележом не везёт.","kind":"in"},{"who":"Без имени","text":"Мне всё ещё не нравится, как получилось. Но назад это уже не отмотать.","kind":"in"},{"who":"Без имени","text":"Ты кому-нибудь успел пересказать вчерашнее?","kind":"in"}],"choices":[{"id":"A","title":"Не распространять признание","echo":"Твоё признание осталось в переписке. Я не передавал его по городу.","set":{"killer_reply":"private"},"lines":[{"who":"Без имени","text":"Ладно. Хотя странно тебя за это благодарить. Мы даже не знакомы.","kind":"in"}],"note":""},{"id":"B","title":"Не обещать секретности","echo":"Я не обещал хранить твои признания в тайне.","set":{"killer_reply":"boundaries"},"lines":[{"who":"Без имени","text":"Разумно. Я тоже тебе ничего хорошего не обещал. Просто написал, потому что надо было кому-то написать.","kind":"in"}],"note":""},{"id":"C","title":"Закончить разговор","echo":"Никакого разговора про деньги больше не хочу.","set":{"killer_reply":"block"},"lines":[{"who":"Без имени","text":"Тогда и не будет. Я свою часть уже получил. Продолжения по этому поводу не планирую.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_mode":"refuse"},"lines":[{"who":"Без имени","text":"Ты вчера отказался помогать — помню. Не переживай, без тебя справились.","kind":"in"}]},{"when":{"cross_mode":"mention"},"lines":[{"who":"Без имени","text":"И ещё: чужую голову я не трогал. Мне хватает собственных неприятностей.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Без имени","text":"А тут ещё какие-то идиоты в районном чате решили, что я с пакетом хожу. Какой-то жутко активный следователь без удостоверения.","kind":"in"}]}]},{"id":"F06","title":"Пятница, 13:34 — Что видел Томазик","chat":"Томазик","core":[{"who":"Томазик","text":"Мужик с хлебом опять заходил. Стоял у кассы, сдачу пересчитывал минуту.","kind":"in"},{"who":"Томазик","text":"Я его спросил, почему он вчера так много взял. Говорит: «Чтоб хватило». На что — не уточнял.","kind":"in"},{"who":"Томазик","text":"Алла сейчас у остановки. Смотрит на тот дом и злится. Не похоже на неё.","kind":"in"},{"who":"Томазик","text":"Мне передать ей что-нибудь?","kind":"in"}],"choices":[{"id":"A","title":"Предложить безопасный вызов помощи","echo":"Если она слышала просьбы о помощи, пусть вызывает службы. И сама не входит.","set":{"help_route":"official"},"lines":[{"who":"Томазик","text":"Скажу. Она и сама, кажется, к этому пришла. Я тут за кассу вернусь, а то очередь смотрит как на врага.","kind":"in"}],"note":""},{"id":"B","title":"Не подтверждать догадки","echo":"Передай, что мы не знаем, кто там. Пусть не рискует из-за слухов.","set":{"help_route":"cautious"},"lines":[{"who":"Томазик","text":"Так и передам. Ничего о подвале от себя добавлять не буду.","kind":"in"}],"note":""},{"id":"C","title":"Разрешить ей решать самой","echo":"Пусть сама решит, что делать. Я не видел этого дома.","set":{"help_route":"hands_off"},"lines":[{"who":"Томазик","text":"Ладно. Я и не собирался командовать. Но если кто из них зайдёт за хлебом, я запомню.","kind":"in"}],"note":""}],"variants":[{"when":{"alla_detail":"warning"},"lines":[{"who":"Томазик","text":"Алла сказала, что ты предположил человека внизу. Она не уверена, но теперь относится серьёзнее.","kind":"in"}]},{"when":{"alla_detail":"sound"},"lines":[{"who":"Томазик","text":"Алла показала мне время стука на телефоне. Я в то время холодильник выключал. Прямо как наш компрессор.","kind":"in"}]},{"when":{"alla_detail":"gentle"},"lines":[{"who":"Томазик","text":"Она сказала, что ты не велел ей ничего расследовать. Правильно, она и так устаёт.","kind":"in"}]}]},{"id":"F07","title":"Пятница, 15:09 — С другого света","chat":"Шурик","core":[{"who":"Шурик","text":"Привет ещё раз. Я нашёл Кольку. Не того, о котором говорил, а вообще другого. Номеров у меня, оказывается, двадцать семь одинаковых.","kind":"in"},{"who":"Шурик","text":"Ничего. Вышло даже хорошо. Этот Колька женился. Счастливый, аж противно.","kind":"in"},{"who":"Шурик","text":"Тебя не достал вчера? А то я тогда что-то разговорился.","kind":"in"}],"choices":[{"id":"A","title":"Поддержать разговор","echo":"Всё нормально. Рад, что у тебя там хорошо.","set":{"shura_friday":"warm"},"lines":[{"who":"Шурик","text":"И я рад. Представляешь: двадцать лет мечтаешь, чтобы никто не звонил по делу, а потом сам всем пишешь.","kind":"in"}],"note":""},{"id":"B","title":"Спросить про старые долги","echo":"Ты действительно решил больше никому ничего не предъявлять?","set":{"shura_friday":"debt"},"lines":[{"who":"Шурик","text":"Решил. Сколько можно предъявлять. От этой бухгалтерии даже море хуже видно.","kind":"in"}],"note":""},{"id":"C","title":"Закрыть чат","echo":"Нет проблем. Я занят, Шур.","set":{"shura_friday":"short"},"lines":[{"who":"Шурик","text":"Понял. Бывай. Если ещё позвоню, значит, опять номер перепутал.","kind":"in"}],"note":""}],"variants":[{"when":{"shurik_mode":"truth"},"lines":[{"who":"Шурик","text":"Да, я всё ещё помню, что ты не Димон. Хоть кто-то тут держит в голове факты.","kind":"in"}]},{"when":{"shurik_mode":"friendly"},"lines":[{"who":"Шурик","text":"Ты даже не спрашиваешь, где точно живу. Хороший подход к чужой жизни.","kind":"in"}]}]},{"id":"F08","title":"Пятница, 17:43 — Правильная теория","chat":"Марат (версии)","core":[{"who":"Марат","text":"Слушай, у меня интересное открытие.","kind":"in"},{"who":"Марат","text":"Я вчера написал людям про странные совпадения. В ответ получил пятнадцать историй про пропавшие вещи, три про соседей и одну про сломанный лифт.","kind":"in"},{"who":"Марат","text":"Ни одна из них, кажется, не имеет отношения к твоей.","kind":"in"},{"who":"Марат","text":"Я теперь не могу понять, был ли вообще смысл спрашивать.","kind":"in"}],"choices":[{"id":"A","title":"Признать ограниченность версий","echo":"Вопросы нормальные. Беда начинается, когда догадки выдают за факты.","set":{"mara_reply":"learn"},"lines":[{"who":"Марат","text":"Справедливо. Мне надо научиться останавливаться до той части, где я рисую стрелки на обоях.","kind":"in"}],"note":""},{"id":"B","title":"Попросить убрать слух","echo":"Лучше удали публикацию про голову. Хозяину квартиры от неё неприятности.","set":{"mara_reply":"remove"},"lines":[{"who":"Марат","text":"Удалю. Если кто сохранил — поздно. Но хотя бы сам продолжать не буду.","kind":"in"}],"note":""},{"id":"C","title":"Оставить его с его выводами","echo":"Тебе виднее. Я не собираюсь спорить весь вечер.","set":{"mara_reply":"leave"},"lines":[{"who":"Марат","text":"Ладно. Я и сам устал. Пойду поем. Если вдруг выяснится, что всё вообще не связано, напиши. Это был бы хороший финал.","kind":"in"}],"note":""}],"variants":[{"when":{"theory_mode":"spread"},"lines":[{"who":"Марат","text":"И да, тот вчерашний пост разошёлся. Меня уже трое спросили, где именно всё случилось. Я им адреса не давал.","kind":"in"}]},{"when":{"theory_mode":"challenge"},"lines":[{"who":"Марат","text":"Ты вчера правильно попросил факт. Я так ни одного и не нашёл.","kind":"in"}]},{"when":{"theory_mode":"ignore"},"lines":[{"who":"Марат","text":"Ты вчера меня проигнорировал, но я всё равно пишу. Больше поговорить не с кем.","kind":"in"}]}]},{"id":"F09","title":"Пятница, 20:12 — В подполе","chat":"Алла","core":[{"who":"Алла","text":"Уже вечером хотела выключить телефон, но напишу.","kind":"in"},{"who":"Алла","text":"Там сегодня снова был шум. Я сама не заходила, можешь не ругаться.","kind":"in"},{"who":"Алла","text":"Томазик сказал, что вы уже обсуждали дом. Я не строю догадки. Просто знаю, что слышала.","kind":"in"},{"who":"Алла","text":"И теперь мне надо решать, что делать с этим знанием.","kind":"in"}],"choices":[{"id":"A","title":"Поддержать обращение за помощью","echo":"Если подозреваешь, что человеку грозит опасность, обратись в службы. Только сама не заходи.","set":{"alla_final":"help"},"lines":[{"who":"Алла","text":"Так и сделаю. Не ради детектива. Просто не хочу потом думать, что ничего не сказала.","kind":"in"}],"note":""},{"id":"B","title":"Попросить сообщать факты","echo":"Сохрани время и то, что слышала. Не нужно самой проверять подвал.","set":{"alla_final":"record"},"lines":[{"who":"Алла","text":"Записала всё, что помню. Тут сложно ошибиться, когда дом под боком.","kind":"in"}],"note":""},{"id":"C","title":"Не давить на неё","echo":"Решай сама. Я не был там и не могу за тебя ответить.","set":{"alla_final":"autonomy"},"lines":[{"who":"Алла","text":"Спасибо, что хотя бы этого не отнимаешь. Я поговорю с Томазиком утром.","kind":"in"}],"note":""}],"variants":[{"when":{"help_route":"official"},"lines":[{"who":"Алла","text":"Томазик уже рассказал мне, что можно попросить помощи, не входя в дом. Я об этом и думала.","kind":"in"}]},{"when":{"help_route":"cautious"},"lines":[{"who":"Алла","text":"То, что ты не выдаёшь подозрения за знания, я ценю. Другие так не умеют.","kind":"in"}]},{"when":{"help_route":"hands_off"},"lines":[{"who":"Алла","text":"Да, мне сказали, что ты не хочешь вмешиваться. Я за тебя и не решила.","kind":"in"}]}]},{"id":"F10","title":"Пятница, 22:10 — Кухня","chat":"Серёга","core":[{"who":"Серёга","text":"Ну что. Пятница закончилась. Я наконец купил чайник.","kind":"in"},{"who":"Серёга","text":"Заодно взял хлеба. Чувствую, что мне теперь хлеб будет сниться до конца жизни.","kind":"in"},{"who":"Серёга","text":"С историей на кухне никакой красивой разгадки не получилось.","kind":"in"},{"who":"Серёга","text":"Ты, кстати, не жалеешь, что я тебе тогда написал?","kind":"in"}],"choices":[{"id":"A","title":"Ответить по-дружески","echo":"Не жалею. Просто странное было утро.","set":{"sergey_final":"friend"},"lines":[{"who":"Серёга","text":"Странное — да. Но я ещё всё-таки люблю обычные утра. Даже после такого.","kind":"in"}],"note":""},{"id":"B","title":"Поставить границу","echo":"Пиши, конечно. Но чужие фотографии больше без предупреждения не присылай.","set":{"sergey_final":"boundary"},"lines":[{"who":"Серёга","text":"Договорились. Следующее фото будет котлеты. Если котлета не окажется чужой головой.","kind":"in"}],"note":""},{"id":"C","title":"Не искать обязательный ответ","echo":"Не на всё найдётся ответ. Иногда можно просто жить дальше.","set":{"sergey_final":"accept"},"lines":[{"who":"Серёга","text":"Это мой любимый вариант. Я и так чайник из-за этой истории чуть не похоронил.","kind":"in"}],"note":""}],"variants":[{"when":{"head_first":"police"},"lines":[{"who":"Серёга","text":"Кому нужно разбираться, теперь разбираются. Мне только сказали пока не уничтожать переписку.","kind":"in"}]},{"when":{"theory_mode":"spread"},"lines":[{"who":"Серёга","text":"Марат там, кстати, себе целый детектив написал. Мне теперь соседи соболезнуют. Хотя я живой.","kind":"in"}]},{"when":{"mara_reply":"remove"},"lines":[{"who":"Серёга","text":"Слух хоть перестал разрастаться. За это спасибо.","kind":"in"}]},{"when":{"photo_route":"private"},"lines":[{"who":"Серёга","text":"Спасибо, что не гонял фото по знакомым без спроса. Я это заметил.","kind":"in"}]}]},{"id":"F11","title":"Суббота, 08:06 — Разные дела","chat":"Валерик","core":[{"who":"Валерик","text":"Утро. Я решил написать тебе один раз и потом заняться своим.","kind":"in"},{"who":"Валерик","text":"Андрей мёртв. Список извлечён. Деньги разделены. Это всё, что я точно знаю о нашей истории.","kind":"in"},{"who":"Валерик","text":"А что там у людей на кухне, под полом и за магазином — у них свои дела. Ты не обязан собирать из них одну картину.","kind":"in"},{"who":"Валерик","text":"Был от тебя толк хотя бы как от собеседника?","kind":"in"}],"choices":[{"id":"A","title":"Остаться на связи","echo":"В чём-то да. Своё закончи сам, а я со своими людьми разберусь.","set":{"chapter_end":"open"},"lines":[{"who":"Валерик","text":"Вот. Разумно. Но кофе в следующий раз оплачиваешь ты.","kind":"in"}],"note":""},{"id":"B","title":"Закрыть неприятную линию","echo":"Я твоё признание и твои деньги больше обсуждать не хочу.","set":{"chapter_end":"close"},"lines":[{"who":"Валерик","text":"Это твоё право. Я, кстати, тоже хочу поговорить о чём-нибудь кроме мозга покойника.","kind":"in"}],"note":""},{"id":"C","title":"Спросить о последствиях","echo":"Убитого не вернёшь, но у этой истории же ещё будут последствия?","set":{"chapter_end":"questions"},"lines":[{"who":"Валерик","text":"Разумеется будут. Дело сделано не значит дело забыто. Ты только не проси меня придумывать их заранее.","kind":"in"}],"note":""}],"variants":[{"when":{"killer_reply":"private"},"lines":[{"who":"Валерик","text":"Убийца сказал, что ты не разносил его слова. Он, по-моему, даже смутился.","kind":"in"}]},{"when":{"killer_reply":"boundaries"},"lines":[{"who":"Валерик","text":"Убийца сказал, что ты ничего не обещал. Нормальный подход, учитывая, что вас вообще не знакомили.","kind":"in"}]},{"when":{"killer_reply":"block"},"lines":[{"who":"Валерик","text":"С ним я договорился. Тебя он, насколько знаю, больше беспокоить не будет.","kind":"in"}]},{"when":{"alla_final":"help"},"lines":[{"who":"Система","text":"Алла решила обратиться за помощью. Подтверждения о судьбе Шомпола у игрока пока нет.","kind":"sys"}]},{"when":{"alla_final":"record"},"lines":[{"who":"Система","text":"Алла сохранила время и подробности, но исход событий в подполе пока неизвестен.","kind":"sys"}]},{"when":{"alla_final":"autonomy"},"lines":[{"who":"Система","text":"Алла оставила решение за собой; сообщений о результатах пока нет.","kind":"sys"}]}]}]};
